631								<input type="email" id="email" name="email" autocomplete="email" inputmode="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help email-error">
632								<span id="email-error" class="error-message" aria-live="polite"></span>
633								<small id="email-help" class="form-hint">For example, name@example.com</small>
634							</div>
